from hydra_zen import zen, ZenStore
store = ZenStore()
@store(name="my_app") def task_function(player1: str, player2: str): with open("player_log.txt", "w") as f: f.write("Game session log:\n") f.write(f"Player 1: {player1}\n" f"Player 2: {player2}")
return player1, player2
if __name__ == "__main__": store.add_to_hydra_store() zen(task_function).hydra_main(config_name="my_app", version_base="1.1", config_path=None, )
